"""Post-scaffold setup for the Mantle (`mantle`) `rasa init` engine.

Runs once the Mantle project template has been copied into the target
directory: secrets collection, agent-skills installation, MCP server
registration, and an optional validate-then-train pass, finishing with the
same "next steps" / Inspector offer as the legacy CALM path
(`rasa.cli.scaffold.print_run_or_instructions`).

The skills and the MCP server are installed together on purpose: the bundled
sim/eval skill drives simulation through the `rasa-tools` MCP server, so
installing the skill without registering that server leaves the coding agent
with instructions it cannot follow.

Every step here is best-effort and non-fatal: a missing credential, a flaky
skills install, or a validation/training failure prints a clear message and
lets `rasa init` finish successfully rather than aborting scaffolding.
An invalid or blank license skips train / Inspector but still installs skills,
registers the MCP server, and prints next steps.
"""

from __future__ import annotations

import argparse
from pathlib import Path
from typing import List, Optional, Text

import structlog

from rasa.cli.mantle_secrets import (
    apply_secrets_to_environ,
    collect_secrets,
    write_env_file,
)
from rasa.cli.tools.constants import (
    ENGINE_MANTLE,
    IDE_DISPLAY_NAMES,
    MCP_TOOLS_TRANSPORT_STDIO,
)
from rasa.shared.constants import DEFAULT_MODELS_PATH
from rasa.shared.project_structure import MANTLE_AGENT_FILE
from rasa.shared.utils.cli import print_error, print_info, print_success, print_warning
from rasa.utils.beta import print_mantle_experimental_info

structlogger = structlog.get_logger(__name__)

# IDEs the bundled agent skills are installed for by default. Matches the
# coding-agent skills ship for today; kept in sync manually since it is not
# derived from `rasa.cli.tools.constants.SUPPORTED_IDES` (that list includes
# IDEs without bundled skill support, e.g. jetbrains).
DEFAULT_SKILLS_IDES: List[Text] = ["claude", "cursor"]


def run_post_scaffold(args: argparse.Namespace, project_dir: Path) -> None:
    """Run the Mantle-only setup steps after the project has been scaffolded.

    Args:
        args: Parsed `rasa init` CLI arguments; reads `no_prompt` and
            `no_train`.
        project_dir: Absolute path to the freshly scaffolded project. The
            process's cwd has already been changed to this directory by
            `rasa.cli.scaffold.init_project`.
    """
    print_info("\nSetting up your Mantle agent...")
    print_mantle_experimental_info()

    secret_values = collect_secrets(assume_yes=args.no_prompt)
    write_env_file(project_dir, secret_values)
    # Disk write alone is not enough: validate/train/Inspector run in this
    # process and read credentials from the environment.
    apply_secrets_to_environ(secret_values)
    # Startup skipped license checks for ``rasa init`` so secrets could be
    # collected first. Soft-check here: blank/invalid licenses must not abort
    # scaffolding, but licensed steps (train / Inspector) are skipped.
    license_ok = _license_is_valid()

    _install_skills(project_dir, assume_yes=args.no_prompt)
    _configure_mcp_tools(project_dir)
    # Before the train block on purpose: the docs are what the coding agent reads,
    # so they must land even when training is skipped or the license is blank.
    _install_docs(project_dir, assume_yes=args.no_prompt)

    trained_model: Optional[Text] = None
    if _should_validate_and_train(args):
        if not license_ok:
            print_warning(
                "Skipping validation and training because no valid "
                "RASA_LICENSE is available."
            )
            print_info(
                "Set RASA_LICENSE in the project `.env` (or your environment), "
                "then run 'rasa train'."
            )
        else:
            trained_model = _validate_and_train(project_dir)
    else:
        print_info("Skipping validation and training.")

    _finale(args, trained_model)


def _license_is_valid() -> bool:
    """Return whether the process environment has a usable Rasa license.

    ``validate_license_from_env`` exits the process on failure; catch that so
    a blank interactive secret cannot abort the rest of ``rasa init``.
    """
    from rasa.utils.licensing import validate_license_from_env

    try:
        validate_license_from_env()
    except SystemExit as error:
        message = str(error).strip() or "License validation failed."
        print_warning(message)
        return False
    return True


def _install_skills(project_dir: Path, *, assume_yes: bool) -> None:
    """Install bundled agent skills for the Mantle engine (best-effort).

    Never aborts `rasa init`: any failure prints a warning with a manual
    retry hint and execution continues.

    Args:
        project_dir: Absolute path to the scaffolded project.
        assume_yes: Non-interactive mode; skips confirmation prompts inside
            the installer.
    """
    print_info("Installing agent skills...")
    try:
        from rasa.cli.tools.skills import install_agent_skills

        installed = install_agent_skills(
            project_dir,
            DEFAULT_SKILLS_IDES,
            non_interactive=assume_yes,
            engine=ENGINE_MANTLE,
        )
    except Exception as e:
        # Best-effort step (see module docstring): a broken skills install
        # must never abort `rasa init`, so we catch broadly, log, and warn.
        structlogger.warning(
            "cli.mantle_init.install_skills.failed",
            event_info=f"Could not install agent skills: {e}",
        )
        print_warning(f"Could not install agent skills: {e}")
        print_info(
            "You can retry later by running 'rasa skills install mantle' "
            "inside the project directory."
        )
        return

    if not installed:
        print_warning("Agent skills were not installed.")
        print_info(
            "You can retry later by running 'rasa skills install mantle' "
            "inside the project directory."
        )


def _configure_mcp_tools(project_dir: Path) -> None:
    """Register the Rasa MCP server for the same IDEs the skills target.

    The bundled sim/eval skill drives simulation through the `rasa-tools` MCP
    server. A stdio server has to be spawned by the IDE client, so scaffolding
    writes the same `.rasa/tools.yaml` and per-IDE MCP config that
    `rasa tools init` would.

    Never aborts `rasa init`: any failure prints a warning naming the manual
    command and execution continues.

    Args:
        project_dir: Absolute path to the scaffolded project.
    """
    print_info("Configuring the Rasa MCP server...")
    try:
        from rasa.cli.tools.init import write_tools_config
        from rasa.cli.tools.models import RunConfig

        write_tools_config(
            project_dir,
            RunConfig(
                mode=MCP_TOOLS_TRANSPORT_STDIO,
                project_path=str(project_dir),
                ide_integrations=DEFAULT_SKILLS_IDES,
            ),
        )
    except Exception as e:
        # Best-effort step (see module docstring): a project without MCP config
        # is still a usable project, so we catch broadly, log, and warn.
        structlogger.warning(
            "cli.mantle_init.configure_mcp_tools.failed",
            event_info=f"Could not configure the Rasa MCP server: {e}",
        )
        print_warning(f"Could not configure the Rasa MCP server: {e}")
        print_info(
            "You can retry later by running 'rasa tools init' inside the "
            "project directory."
        )
        return

    ide_names = ", ".join(
        IDE_DISPLAY_NAMES.get(ide, ide) for ide in DEFAULT_SKILLS_IDES
    )
    print_success(f"Registered the Rasa MCP server for {ide_names}.")
    print_info(
        "Restart your coding agent in this directory so it picks up the "
        "new MCP server."
    )


def _install_docs(project_dir: Path, *, assume_yes: bool) -> None:
    """Download the Mantle docs bundle for local agent lookup (best-effort).

    Never aborts `rasa init`: any failure prints a warning and execution
    continues.  The installed agent skills fall back to the online docs when
    the local bundle is absent, so a failed download degrades rather than
    breaks.

    Args:
        project_dir: Absolute path to the scaffolded project.
        assume_yes: Non-interactive mode; skips confirmation prompts inside
            the fetcher.
    """
    print_info("Downloading Mantle documentation for your coding agent...")
    try:
        from rasa.cli.tools.docs import fetch_mantle_docs

        fetch_mantle_docs(project_dir, non_interactive=assume_yes)
    except Exception as e:
        # Best-effort step (see module docstring): a failed or blocked download
        # must never abort `rasa init`, so we catch broadly, log, and warn.
        structlogger.warning(
            "cli.mantle_init.install_docs.failed",
            event_info=f"Could not download Mantle documentation: {e}",
        )
        print_warning(f"Could not download Mantle documentation: {e}")
        print_info(
            "Your coding agent will fall back to the online docs. Retry later "
            "by running 'rasa tools init docs mantle' inside the project "
            "directory."
        )


def _should_validate_and_train(args: argparse.Namespace) -> bool:
    """Decide whether to validate then train, honoring `--no-train`/`--no-prompt`.

    Args:
        args: Parsed `rasa init` CLI arguments.

    Returns:
        True if validation and training should run.
    """
    if getattr(args, "no_train", False):
        return False

    import questionary

    return bool(
        questionary.confirm("Validate and train your agent now?")
        .skip_if(args.no_prompt, default=True)
        .ask()
    )


def _validate_and_train(project_dir: Path) -> Optional[Text]:
    """Validate the project, then package a model archive if it's valid.

    Both steps are best-effort: any failure is printed and swallowed so
    `rasa init` still finishes successfully. Training only runs when
    validation passed, so a broken project is never packaged.

    Args:
        project_dir: Absolute path to the scaffolded project (also the
            process's current working directory).

    Returns:
        The path to the packaged model archive on success; `None` if
        validation or training failed.
    """
    from rasa.exceptions import ValidationError
    from rasa.mantle.validation import validate_project

    print_info("Validating your agent...")
    try:
        validate_project(project_dir)
    except ValidationError as e:
        print_error(f"Validation failed: {e}")
        print_info("Fix the issues above, then run 'rasa train'.")
        return None
    except Exception as e:
        # Best-effort step (see module docstring): an unexpected validation
        # error must not abort `rasa init`.
        structlogger.exception(
            "cli.mantle_init.validate_project.unexpected_error", exc_info=e
        )
        print_error(f"Validation failed unexpectedly: {e}")
        return None
    print_success("Validation passed.")

    print_info("Training your agent...")
    try:
        from rasa.mantle.model_archive.snapshot import package_model_archive

        result = package_model_archive(
            config_path=str(project_dir / MANTLE_AGENT_FILE),
            output=DEFAULT_MODELS_PATH,
            validate=False,
        )
    except Exception as e:
        # Best-effort step (see module docstring): training must never abort
        # `rasa init`, even on an unexpected error.
        structlogger.exception(
            "cli.mantle_init.package_model_archive.unexpected_error", exc_info=e
        )
        print_error(f"Training failed: {e}")
        print_info("Fix the issue above, then run 'rasa train'.")
        return None

    print_success("Training complete.")
    return result.model


def _finale(args: argparse.Namespace, trained_model: Optional[Text]) -> None:
    """Offer to open the Inspector after a successful train, else print next steps.

    Args:
        args: Parsed `rasa init` CLI arguments.
        trained_model: Path to the packaged model archive, or `None` if
            validation/training did not run or failed.
    """
    if trained_model is not None:
        from rasa.cli.scaffold import print_run_or_instructions

        args.model = trained_model
        print_run_or_instructions(args)
        return

    if args.no_prompt:
        print_info(
            "Once you're ready, run 'rasa train', then 'rasa inspect' "
            "to talk to your agent."
        )
    else:
        print_success(
            "Ok 👍🏼. You can train and inspect your agent any time by "
            "running 'rasa train' and 'rasa inspect' inside the project "
            "directory."
        )
